//! Byte-exact SMAUG-T IND-CPA decryption differential tests.
//! Inputs are independently generated by the pinned C reference.

use pqc_rs_smaug_t::indcpa::decrypt;
use pqc_rs_smaug_t::{Parameters, SMAUG_T128, SMAUG_T192, SMAUG_T256, TIMER};
use std::fs;
use std::path::Path;

fn decode_hex(input: &str) -> Vec<u8> {
    assert_eq!(input.len() % 2, 0, "odd hexadecimal length");

    input
        .as_bytes()
        .chunks_exact(2)
        .map(|pair| {
            let text = std::str::from_utf8(pair).expect("hex UTF-8");
            u8::from_str_radix(text, 16).expect("valid hex")
        })
        .collect()
}

fn field<'a>(line: &'a str, label: &str) -> &'a str {
    line.strip_prefix(label)
        .unwrap_or_else(|| panic!("missing oracle field {label}"))
}

fn assert_exact(mode: &str, case: usize, actual: &[u8], expected: &[u8]) {
    assert_eq!(
        actual.len(),
        expected.len(),
        "{mode} case={case}: recovered message length mismatch"
    );

    if let Some((index, (&found, &wanted))) = actual
        .iter()
        .zip(expected)
        .enumerate()
        .find(|(_, (a, b))| a != b)
    {
        panic!(
            "{mode} case={case}: decryption mismatch at byte {index}: \
             Rust={found:02x}, C={wanted:02x}"
        );
    }
}

fn check_mode(
    root: &Path,
    mode: &str,
    parameters: &Parameters,
    message_len: usize,
    secret_key_len: usize,
    ciphertext_len: usize,
) -> usize {
    let path = root.join(format!("decrypt-{mode}.txt"));

    let content = fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display()));

    let lines: Vec<_> = content.lines().collect();

    assert_eq!(lines.len(), 24, "{mode}: expected 24 oracle records");

    for case in 0..4 {
        let base = case * 6;

        assert_eq!(lines[base], format!("CASE={case}"));

        let pk = decode_hex(field(lines[base + 1], "PK="));
        let sk = decode_hex(field(lines[base + 2], "SK="));
        let ct = decode_hex(field(lines[base + 3], "CT="));
        let message = decode_hex(field(lines[base + 4], "MSG="));
        let c_recovered = decode_hex(field(lines[base + 5], "DEC="));

        assert_eq!(
            pk.len(),
            32 + parameters.k * 256 * parameters.q.trailing_zeros() as usize / 8
        );
        assert_eq!(sk.len(), secret_key_len);
        assert_eq!(ct.len(), ciphertext_len);
        assert_eq!(message.len(), message_len);
        assert_eq!(c_recovered.len(), message_len);

        assert_exact(mode, case, &c_recovered, &message);

        // The C-generated SK and CT are passed directly to Rust.
        let rust_recovered = decrypt(&sk, &ct, parameters)
            .unwrap_or_else(|error| panic!("{mode} case={case}: Rust decryption error: {error:?}"));

        assert_exact(mode, case, &rust_recovered, &c_recovered);

        println!(
            "S4_5C_3_MODE={mode} CASE={case} \
             DECRYPT=PASS MESSAGE_BYTES={message_len}"
        );
    }

    println!("S4_5C_3_MODE={mode} CASES=4 MISMATCHES=0 STATUS=PASS");

    4 * message_len
}

#[test]
fn reference_indcpa_decrypt_parity_all_modes() {
    let root = match std::env::var("SMAUGT_DECRYPT_ORACLE") {
        Ok(value) => value,
        Err(_) => {
            eprintln!(
                "S4_5C_3_SKIPPED: set SMAUGT_DECRYPT_ORACLE \
                 to execute reference parity"
            );
            return;
        }
    };

    let root = Path::new(&root);
    assert!(root.is_dir(), "oracle directory does not exist");

    let total = [
        ("mode1", SMAUG_T128, 32, 128, 672),
        ("mode3", SMAUG_T192, 32, 192, 992),
        ("mode5", SMAUG_T256, 32, 256, 1376),
        ("modet", TIMER, 16, 128, 608),
    ]
    .iter()
    .map(|(mode, parameters, message_len, sk_len, ct_len)| {
        check_mode(root, mode, parameters, *message_len, *sk_len, *ct_len)
    })
    .sum::<usize>();

    assert_eq!(total, 448);

    println!(
        "S4_5C_3_DECRYPT_PARITY=PASS \
         CASES=16 MESSAGE_BYTES={total} MISMATCHES=0"
    );
}
